from operator import add
from typing import Annotated, Literal

from pydantic import BaseModel, Field

class AgentSchema(BaseModel):
    messages: Annotated[list,add] = Field(..., description="List of messages to be processed by the agent")
    curated_question: Annotated[str,add] = Field(..., description="Curated question generated by the agent based on the user input and messages")   
    prompt_query_context: Annotated[str,add] = Field(..., description="Contextual information on SQL Database and data engineering to assist the agent in generating relevant responses")
    is_safe: Literal['safe', 'unsafe'] = Field(..., description="Indicates whether the SQL query generated by the agent is safe or unsafe based on the curated question and prompt query context")
    generated_sql_query: Annotated[str,add] = Field(..., description="SQL query generated by the agent based on the curated question and prompt query context")
    sql_query_results: Annotated[str,add] = Field(..., description="Results of the SQL query executed against the database, providing relevant information to the agent for generating responses")
    final_response: Annotated[str,add] = Field(..., description="Final response generated by the agent based on the curated question, prompt query context, and SQL query results")